#!/bin/bash
# Task 094 -- meshsim v1.25 freeze check, part 2 (WORKER11): main at 922b835, run_tests.sh's quick suite (8 at a time)
# and its full-mode extras (4 at a time). A rerun of task 093's suites: 093's kit left out the controllers' firmware
# (sw/build_cc.sh, new with cc-cores), so CcCoresTest, RecipeTest's cc1 driver and CcBench couldn't find their images.
# 093's p4/uniform-k128 (1,229,008 cycles) and the selected windows (12 + 13, stages A, B, F) passed and aren't repeated.
# The kit (wip/ at Java 17 with every image prebuilt, the firmware included) is embedded below, SHA-256 checked; the
# three failed steps passed locally from this build. Expected ~10 min. No code changes.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/094-w11-v125-freeze-suites; mkdir -p "$RES"
WANT=4106c2e7285e830cb46179d9b4906f7126a6be4cbc0e71d4b2b24b05f5720379
W=/tmp/w11-094; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/wip/meshsim" || exit 2
P=8 ./run_quick.sh "$W/out"; RQ=$?
P=4 ./run_full.sh "$W/out"; RF=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF at $(date -u)"
cp "$W"/out/* "$RES/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RF = 0 ]; exit $?
